import re,glob,sys
N='hideHint'
tag=re.compile(r'<app-(?:pill|fancy-pill|status-pill)(?=[\s>/])[^>]*>',re.S)
def tagfix(m): return re.sub(r'(?<![\w-])(\[?)disableTooltip(?![\w-])',r'\1'+N,m.group(0))
def expr(s):
    return re.sub(r'(?<!summary)(?<!card\(\)\?)\.disableTooltip\(\)','.'+N+'()',s)
for f in glob.glob('src/app/features/**/*',recursive=True):
    if not f.endswith(('.ts','.html')): continue
    s=open(f,encoding='utf8',newline='').read(); o=s
    s=tag.sub(tagfix,s); s=expr(s)
    if s!=o: open(f,'w',encoding='utf8',newline='').write(s)
def sub(f,fn):
    s=open(f,encoding='utf8',newline='').read(); s=fn(s); open(f,'w',encoding='utf8',newline='').write(s)
L='src/app/lib/'
for f in ['pill','fancy-pill','status-pill']:
    sub(L+f+'.component.ts',lambda s:s.replace('disableTooltip',N))
sub(L+'pill-tray.component.ts',lambda s:s.replace('pill.setInput("disableTooltip"','pill.setInput("'+N+'"'))
sub('src/styles.css',lambda s:'\n'.join(l.replace('disableTooltip',N) if re.match(r'app-(pill|fancy|status)',l) else l for l in s.split('\n')))
E
python /tmp/r.py; git diff --stat | tail -1; npx ngc -p tsconfig.json | head -20; grep -rn "disableTooltip" src --include=*.css --include=pill-tray* ; git diff src/styles.css | grep '^[+-]'

